package com.friendaliases;

import com.google.common.base.Strings;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Persists a friend's alias keyed by their normalised username.
 */
@Singleton
class AliasStore
{
	private static final String KEY_PREFIX = "alias_";
	private static final String ALIAS_KEYS_PREFIX = FriendAliasesConfig.GROUP + "." + KEY_PREFIX;

	private final ConfigManager configManager;

	@Inject
	AliasStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	@Nullable
	String get(String username)
	{
		if (Strings.isNullOrEmpty(username))
		{
			return null;
		}
		return configManager.getConfiguration(FriendAliasesConfig.GROUP, keyFor(username));
	}

	void set(String username, String alias)
	{
		if (Strings.isNullOrEmpty(alias))
		{
			remove(username);
			return;
		}
		configManager.setConfiguration(FriendAliasesConfig.GROUP, keyFor(username), alias);
	}

	/**
	 * Finds the username behind an alias, for undoing an alias shown in the UI.
	 * If two friends share an alias, the first match wins.
	 */
	@Nullable
	String usernameForAlias(String alias)
	{
		if (Strings.isNullOrEmpty(alias))
		{
			return null;
		}

		return configManager.getConfigurationKeys(ALIAS_KEYS_PREFIX).stream()
			.map(configKey -> configKey.substring(ALIAS_KEYS_PREFIX.length()))
			.filter(username -> alias.equals(get(username)))
			.findFirst()
			.orElse(null);
	}

	void remove(String username)
	{
		configManager.unsetConfiguration(FriendAliasesConfig.GROUP, keyFor(username));
	}

	void rename(String oldUsername, String newUsername)
	{
		final String alias = get(oldUsername);
		if (alias == null || get(newUsername) != null)
		{
			return;
		}
		remove(oldUsername);
		set(newUsername, alias);
	}

	private static String keyFor(String username)
	{
		return KEY_PREFIX + Text.toJagexName(username);
	}
}

package com.friendaliases;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public enum AliasNameLocation
{
	ABOVE_HEAD("Above head"),
	MODEL_CENTER("Center of model"),
	MODEL_RIGHT("Right of model");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.friendaliases;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(FriendAliasesConfig.GROUP)
public interface FriendAliasesConfig extends Config
{
	String GROUP = "friendaliases";

	@ConfigItem(
		keyName = "namePosition",
		name = "Alias Position",
		description = "Where the alias is drawn relative to the player",
		position = 0
	)
	default AliasNameLocation namePosition()
	{
		return AliasNameLocation.ABOVE_HEAD;
	}

	@Alpha
	@ConfigItem(
		keyName = "aliasColor",
		name = "Alias Color",
		description = "Color of the alias text drawn above friends",
		position = 1
	)
	default Color aliasColor()
	{
		return new Color(0, 255, 0);
	}

	@ConfigItem(
		keyName = "showRealName",
		name = "Show Real Name",
		description = "Also show the real username in parentheses after the alias",
		position = 2
	)
	default boolean showRealName()
	{
		return false;
	}

	@ConfigItem(
		keyName = "labelFriendsWithoutAlias",
		name = "Label All Friends",
		description = "Also draw the real name above friends who don't have an alias set",
		position = 3
	)
	default boolean labelFriendsWithoutAlias()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "friendNameColor",
		name = "Friend Name Color",
		description = "Color of the real name drawn above friends without an alias (when 'Label All Friends' is on)",
		position = 4
	)
	default Color friendNameColor()
	{
		return new Color(0, 200, 83);
	}

	@ConfigItem(
		keyName = "chatAliases",
		name = "Aliases in Chat",
		description = "Show aliases in the chatbox: message senders, private messages, and login notifications",
		position = 5
	)
	default boolean chatAliases()
	{
		return true;
	}

	@ConfigItem(
		keyName = "takeoverPlayerIndicators",
		name = "Take Over Player Indicators",
		description = "Turn off Player Indicators' overhead names so they never overlap.<br>" +
			"Your Player Indicators settings are restored when this is turned off.",
		position = 6
	)
	default boolean takeoverPlayerIndicators()
	{
		return false;
	}

	@ConfigSection(
		name = "Feedback",
		description = "Suggestions, bug reports, and support",
		position = 99
	)
	String feedbackSection = "feedbackSection";

	@ConfigItem(
		keyName = "suggestButton",
		name = "Suggest a feature",
		description = "Have an idea or found a bug? Click the box to open the GitHub issues page",
		section = feedbackSection,
		position = 0
	)
	default boolean suggestButton()
	{
		return false;
	}

	@ConfigItem(
		keyName = "supportButton",
		name = "Buy me a coffee ❤",
		description = "Enjoying the plugin? Click the box to open the Ko-fi page",
		section = feedbackSection,
		position = 1
	)
	default boolean supportButton()
	{
		return false;
	}
}

package com.friendaliases;

import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Disables every Player Indicators highlight category that can draw an overhead name
 * on a friend, remembering each previous value so it can be restored when the
 * takeover is turned off (or this plugin shuts down).
 */
@Singleton
class PlayerIndicatorsTakeover
{
	static final String PI_GROUP = "playerindicators";
	static final String DISABLED = "DISABLED";

	// Player Indicators picks the first matching category in this priority order,
	// so all of them must be off for a friend to never get a second overhead name.
	private static final List<String> HIGHLIGHT_KEYS = List.of(
		"highlightPartyMembers",
		"highlightFriends",
		"highlightFriendsChat",
		"highlightTeamMembers",
		"highlightClanMembers"
	);

	private static final String SAVED_KEY_PREFIX = "takeoverSaved_";
	// Marker for "the key had no stored value", so restore can unset it back to the default
	private static final String SAVED_UNSET = "__unset__";

	private final ConfigManager configManager;

	@Inject
	private PlayerIndicatorsTakeover(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	void apply()
	{
		HIGHLIGHT_KEYS.forEach(this::disable);
	}

	void restore()
	{
		HIGHLIGHT_KEYS.forEach(this::restoreKey);
	}

	private void disable(String key)
	{
		// An existing saved value means a previous takeover was never restored
		// (e.g. the client was killed); keep it rather than saving our own DISABLED.
		if (savedValueOf(key) == null)
		{
			final String current = configManager.getConfiguration(PI_GROUP, key);
			configManager.setConfiguration(FriendAliasesConfig.GROUP, savedKeyFor(key),
				current != null ? current : SAVED_UNSET);
		}

		configManager.setConfiguration(PI_GROUP, key, DISABLED);
	}

	private void restoreKey(String key)
	{
		final String saved = savedValueOf(key);
		if (saved == null)
		{
			return;
		}

		configManager.unsetConfiguration(FriendAliasesConfig.GROUP, savedKeyFor(key));

		final boolean changedByUserSinceTakeover = !DISABLED.equals(configManager.getConfiguration(PI_GROUP, key));
		if (changedByUserSinceTakeover)
		{
			return;
		}

		if (SAVED_UNSET.equals(saved))
		{
			configManager.unsetConfiguration(PI_GROUP, key);
			return;
		}

		configManager.setConfiguration(PI_GROUP, key, saved);
	}

	private String savedValueOf(String key)
	{
		return configManager.getConfiguration(FriendAliasesConfig.GROUP, savedKeyFor(key));
	}

	private static String savedKeyFor(String key)
	{
		return SAVED_KEY_PREFIX + key;
	}
}

package com.friendaliases;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;

@Singleton
public class FriendAliasesOverlay extends Overlay
{
	private static final int ABOVE_HEAD_MARGIN = 40;
	private static final int MODEL_RIGHT_MARGIN = 10;

	private final Client client;
	private final FriendAliasesConfig config;
	private final AliasStore aliasStore;

	@Inject
	private FriendAliasesOverlay(Client client, FriendAliasesConfig config, AliasStore aliasStore)
	{
		this.client = client;
		this.config = config;
		this.aliasStore = aliasStore;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final WorldView top = client.getTopLevelWorldView();
		if (top == null)
		{
			return null;
		}

		renderFriends(graphics, top);
		for (WorldView sub : top.worldViews())
		{
			renderFriends(graphics, sub);
		}
		return null;
	}

	private void renderFriends(Graphics2D graphics, WorldView worldView)
	{
		for (Player player : worldView.players())
		{
			final OverheadLabel label = labelFor(player, worldView);
			if (label != null)
			{
				draw(graphics, player, label);
			}
		}
	}

	private OverheadLabel labelFor(Player player, WorldView worldView)
	{
		if (player == null || player.getName() == null || !player.isFriend())
		{
			return null;
		}

		final LocalPoint location = player.getLocalLocation();
		if (location == null || !worldView.contains(location))
		{
			return null;
		}

		final String username = Text.sanitize(player.getName());
		final String alias = aliasStore.get(username);

		if (alias != null)
		{
			final String text = config.showRealName() ? alias + " (" + username + ")" : alias;
			return new OverheadLabel(text, config.aliasColor());
		}

		if (config.labelFriendsWithoutAlias())
		{
			return new OverheadLabel(username, config.friendNameColor());
		}

		return null;
	}

	private void draw(Graphics2D graphics, Player player, OverheadLabel label)
	{
		final Point anchor = anchorFor(graphics, player, label.getText());
		if (anchor != null)
		{
			OverlayUtil.renderTextLocation(graphics, anchor, label.getText(), label.getColor());
		}
	}

	private Point anchorFor(Graphics2D graphics, Player player, String text)
	{
		final AliasNameLocation position = config.namePosition();
		final int zOffset = zOffsetFor(position, player);

		if (position != AliasNameLocation.MODEL_RIGHT)
		{
			return player.getCanvasTextLocation(graphics, text, zOffset);
		}

		final Point modelEdge = player.getCanvasTextLocation(graphics, "", zOffset);
		return modelEdge == null
			? null
			: new Point(modelEdge.getX() + MODEL_RIGHT_MARGIN, modelEdge.getY());
	}

	private static int zOffsetFor(AliasNameLocation position, Player player)
	{
		switch (position)
		{
			case MODEL_CENTER:
			case MODEL_RIGHT:
				return player.getLogicalHeight() / 2;
			default:
				return player.getLogicalHeight() + ABOVE_HEAD_MARGIN;
		}
	}

	@Value
	private static class OverheadLabel
	{
		String text;
		Color color;
	}
}

package com.friendaliases;

import com.google.common.base.Strings;
import com.google.inject.Provides;
import java.awt.Color;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Friend;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Nameable;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.NameableNameChanged;
import net.runelite.api.events.RemovedFriend;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.events.ConfigChanged;

@PluginDescriptor(
	name = "Friend Aliases",
	description = "Show a custom nickname/alias above your friends' heads instead of their username",
	tags = {"jake", "friend", "friends", "alias", "aliases", "nickname", "nicknames", "name", "rename", "label", "indicator", "overhead", "player", "custom", "chat", "message", "pm", "login"}
)
public class FriendAliasesPlugin extends Plugin
{
	private static final String FRIENDS_LIST_MESSAGE = "Message";
	private static final String SET_ALIAS = "Set Alias";
	private static final String EDIT_ALIAS = "Edit Alias";
	private static final int ALIAS_CHARACTER_LIMIT = 32;
	private static final String ALIAS_PROMPT = "%s's Alias<br>" +
		ColorUtil.prependColorTag("(Limit %s Characters, clear to remove)", new Color(0, 0, 170));
	private static final String LOOKUP_OPTION = "Lookup";
	private static final String TAKEOVER_KEY = "takeoverPlayerIndicators";
	private static final String NUDGE_SHOWN_KEY = "overlapNudgeShown";
	private static final String NUDGE_MESSAGE = "Friend Aliases: Player Indicators is also drawing friend names. " +
		"Enable 'Take Over Player Indicators' in the Friend Aliases settings to avoid overlapping labels.";

	@Inject
	private Client client;

	@Inject
	private FriendAliasesConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PlayerIndicatorsTakeover takeover;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FriendAliasesOverlay overlay;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private AliasStore aliasStore;

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!FriendAliasesConfig.GROUP.equals(event.getGroup()) || event.getNewValue() == null)
		{
			return;
		}

		if (TAKEOVER_KEY.equals(event.getKey()))
		{
			if (Boolean.parseBoolean(event.getNewValue()))
			{
				takeover.apply();
				return;
			}

			takeover.restore();
			return;
		}

		// The config panel cannot host real buttons, so the Feedback "buttons" are checkboxes
		// that act as buttons: any click of the box, tick or untick, opens the link.
		if ("suggestButton".equals(event.getKey()))
		{
			LinkBrowser.browse("https://github.com/jakevollkommer/friend-aliases/issues");
			return;
		}

		if ("supportButton".equals(event.getKey()))
		{
			LinkBrowser.browse("https://ko-fi.com/jakevollkommer");
		}
	}

	@Provides
	FriendAliasesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FriendAliasesConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);

		if (config.takeoverPlayerIndicators())
		{
			takeover.apply();
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		takeover.restore();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			maybeNudgeAboutOverlap();
		}
	}

	private void maybeNudgeAboutOverlap()
	{
		if (config.takeoverPlayerIndicators() || nudgeAlreadyShown() || !playerIndicatorsDrawsFriendNames())
		{
			return;
		}

		configManager.setConfiguration(FriendAliasesConfig.GROUP, NUDGE_SHOWN_KEY, true);
		client.addChatMessage(ChatMessageType.CONSOLE, "", NUDGE_MESSAGE, null);
	}

	private boolean nudgeAlreadyShown()
	{
		return Boolean.TRUE.equals(configManager.getConfiguration(FriendAliasesConfig.GROUP, NUDGE_SHOWN_KEY, Boolean.class));
	}

	private boolean playerIndicatorsDrawsFriendNames()
	{
		return playerIndicatorsPluginEnabled()
			&& !PlayerIndicatorsTakeover.DISABLED.equals(playerIndicatorsSetting("playerNamePosition", "ABOVE_HEAD"))
			// Only nudge for the plain ENABLED default; PVP-only highlighting is a deliberate choice
			&& "ENABLED".equals(playerIndicatorsSetting("highlightFriends", "ENABLED"));
	}

	private boolean playerIndicatorsPluginEnabled()
	{
		final String enabled = configManager.getConfiguration("runelite", "playerindicatorsplugin");
		return enabled == null || Boolean.parseBoolean(enabled);
	}

	private String playerIndicatorsSetting(String key, String defaultValue)
	{
		final String value = configManager.getConfiguration(PlayerIndicatorsTakeover.PI_GROUP, key);
		return value != null ? value : defaultValue;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!isFriendsListMessage(event))
		{
			return;
		}

		final boolean hasAlias = aliasStore.get(usernameOf(event.getTarget())) != null;

		client.createMenuEntry(-1)
			.setOption(hasAlias ? EDIT_ALIAS : SET_ALIAS)
			.setType(MenuAction.RUNELITE)
			.setTarget(event.getTarget())
			.onClick(clicked -> promptForAlias(usernameOf(clicked.getTarget())));
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.chatAliases())
		{
			return;
		}

		if (event.getType() == ChatMessageType.LOGINLOGOUTNOTIFICATION)
		{
			aliasLoginNotification(event);
			return;
		}

		aliasSenderName(event);
	}

	private void aliasSenderName(ChatMessage event)
	{
		final String taggedName = event.getName();
		if (Strings.isNullOrEmpty(taggedName))
		{
			return;
		}

		final String username = usernameOf(taggedName);
		final String alias = aliasStore.get(username);
		if (Strings.isNullOrEmpty(alias))
		{
			return;
		}

		event.getMessageNode().setName(replaceNameKeepingTags(taggedName, chatLabel(alias, username)));
	}

	private void aliasLoginNotification(ChatMessage event)
	{
		final String message = event.getMessage();
		final int suffixStart = message.indexOf(" has logged");
		if (suffixStart == -1)
		{
			return;
		}

		final String username = usernameOf(message.substring(0, suffixStart));
		final String alias = aliasStore.get(username);
		if (Strings.isNullOrEmpty(alias))
		{
			return;
		}

		event.getMessageNode().setValue(chatLabel(alias, username) + message.substring(suffixStart));
	}

	private String chatLabel(String alias, String username)
	{
		return config.showRealName() ? alias + " (" + username + ")" : alias;
	}

	// A tagged name is leading tags (mod crowns, friends chat ranks), the visible name, and
	// trailing tags (closing color tags). Swap the visible name for the label and keep the
	// tags on both sides where they were.
	private static final Pattern NAME_WRAPPED_IN_TAGS = Pattern.compile("((?:<[^>]*>)*)(.*?)((?:<[^>]*>)*)");

	private static String replaceNameKeepingTags(String taggedName, String label)
	{
		final Matcher tagsAroundName = NAME_WRAPPED_IN_TAGS.matcher(taggedName);
		if (!tagsAroundName.matches())
		{
			return label;
		}

		final String leadingTags = tagsAroundName.group(1);
		final String trailingTags = tagsAroundName.group(3);
		return leadingTags + label + trailingTags;
	}

	// The Hiscores plugin builds its chat "Lookup" entry from the chat line's name, which is
	// the alias once we've rewritten the message node. Relabel the entry and redirect the
	// lookup so it targets the actual player.
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.chatAliases())
		{
			return;
		}

		for (MenuEntry entry : event.getMenuEntries())
		{
			redirectLookupToRealUsername(entry);
		}
	}

	private void redirectLookupToRealUsername(MenuEntry entry)
	{
		if (entry.getType() != MenuAction.RUNELITE || !LOOKUP_OPTION.equals(entry.getOption()))
		{
			return;
		}

		final String username = usernameBehindChatLabel(Text.removeTags(entry.getTarget()));
		if (username == null)
		{
			return;
		}

		final Consumer<MenuEntry> hiscoreLookup = entry.onClick();
		if (hiscoreLookup == null)
		{
			// No click handler to redirect, so the target itself must carry the real username
			entry.setTarget(replaceNameKeepingTags(entry.getTarget(), username));
			return;
		}

		entry.setTarget(replaceNameKeepingTags(entry.getTarget(), aliasStore.get(username) + " (" + username + ")"));
		entry.onClick(clicked ->
		{
			clicked.setTarget(replaceNameKeepingTags(clicked.getTarget(), username));
			hiscoreLookup.accept(clicked);
		});
	}

	private String usernameBehindChatLabel(String label)
	{
		final String parenthesizedUsername = usernameFromShowRealNameLabel(label);
		if (parenthesizedUsername != null)
		{
			return parenthesizedUsername;
		}

		return aliasStore.usernameForAlias(label);
	}

	// Undoes chatLabel's "alias (username)" form; returns null if the label isn't one of ours
	private String usernameFromShowRealNameLabel(String label)
	{
		final int usernameStart = label.lastIndexOf(" (");
		if (usernameStart == -1 || !label.endsWith(")"))
		{
			return null;
		}

		final String username = label.substring(usernameStart + 2, label.length() - 1);
		final String alias = label.substring(0, usernameStart);
		return alias.equals(aliasStore.get(username)) ? username : null;
	}

	@Subscribe
	public void onNameableNameChanged(NameableNameChanged event)
	{
		final Nameable nameable = event.getNameable();
		if (nameable instanceof Friend && nameable.getPrevName() != null && nameable.getName() != null)
		{
			aliasStore.rename(nameable.getPrevName(), nameable.getName());
		}
	}

	@Subscribe
	public void onRemovedFriend(RemovedFriend event)
	{
		aliasStore.remove(event.getNameable().getName());
	}

	private void promptForAlias(String username)
	{
		chatboxPanelManager.openTextInput(String.format(ALIAS_PROMPT, username, ALIAS_CHARACTER_LIMIT))
			.value(Strings.nullToEmpty(aliasStore.get(username)))
			.onDone(input -> { saveAlias(username, input); })
			.build();
	}

	private void saveAlias(String username, String input)
	{
		if (input == null)
		{
			return;
		}

		final String alias = Text.removeTags(input).trim();
		aliasStore.set(username, alias.substring(0, Math.min(alias.length(), ALIAS_CHARACTER_LIMIT)));
	}

	private static boolean isFriendsListMessage(MenuEntryAdded event)
	{
		return WidgetUtil.componentToInterface(event.getActionParam1()) == InterfaceID.FRIENDS
			&& event.getOption().equals(FRIENDS_LIST_MESSAGE);
	}

	private static String usernameOf(String menuTarget)
	{
		return Text.toJagexName(Text.removeTags(menuTarget));
	}
